  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
  min-height: 100vh;
  background: linear-gradient(135deg, #e75c8d 0%, #f09286 50%, #f4b397 100%);
  color: white;
  overflow-x: hidden;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2rem 4rem;
  position: relative;
  z-index: 10;
}

.logo {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.language {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  opacity: 0.9;
}

.login {
  color: white;
  text-decoration: none;
  opacity: 0.9;
  transition: opacity 0.2s;
}

.login:hover {
  opacity: 1;
}

.signup {
  background: white;
  color: #e75c8d;
  padding: 0.75rem 2rem;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 500;
  transition: transform 0.2s;
}

.signup:hover {
  transform: translateY(-2px);
}

main {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  align-items: center;
  padding: 0 4rem;
  min-height: calc(100vh - 200px);
  position: relative;
}

.content-left {
  padding-right: 2rem;
}

h1 {
  font-size: 6rem;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: 3rem;
}

.scroll-indicator {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 50px;
  font-size: 0.9rem;
  backdrop-filter: blur(10px);
}

.sphere-container {
  display: flex;
  justify-content: center;
  align-items: center;
  perspective: 1000px;
}

.sphere {
  width: 400px;
  height: 400px;
  position: relative;
  transform-style: preserve-3d;
  animation: float 6s ease-in-out infinite;
}

@keyframes float {
  0%, 100% {
    transform: translateY(0) rotateY(0deg);
  }
  50% {
    transform: translateY(-20px) rotateY(10deg);
  }
}

.slice {
  position: absolute;
  width: 400px;
  height: 80px;
  border-radius: 200px;
  background: linear-gradient(135deg, 
    rgba(255, 255, 255, 0.3) 0%, 
    rgba(255, 255, 255, 0.1) 100%);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 
    0 10px 40px rgba(0, 0, 0, 0.1),
    inset 0 1px 2px rgba(255, 255, 255, 0.5);
}

.slice-1 {
  top: 0;
  transform: translateZ(0);
}

.slice-2 {
  top: 80px;
  transform: translateZ(-20px) translateX(-30px) rotateZ(-5deg);
  opacity: 0.9;
}

.slice-3 {
  top: 160px;
  transform: translateZ(-40px) translateX(-60px) rotateZ(-10deg);
  opacity: 0.8;
}

.slice-4 {
  top: 240px;
  transform: translateZ(-60px) translateX(-90px) rotateZ(-15deg);
  opacity: 0.7;
}

.slice-5 {
  top: 320px;
  transform: translateZ(-80px) translateX(-120px) rotateZ(-20deg);
  opacity: 0.6;
}

.content-right {
  padding-left: 2rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.tagline {
  font-size: 1.5rem;
  font-weight: 300;
  line-height: 1.5;
  opacity: 0.95;
}

.app-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.app-store,
.play-store {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 12px;
  text-decoration: none;
  color: white;
  backdrop-filter: blur(10px);
  background: rgba(255, 255, 255, 0.1);
  transition: all 0.3s;
}

.app-store:hover,
.play-store:hover {
  background: rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
  border-color: rgba(255, 255, 255, 0.5);
}

.app-store div,
.play-store div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.small {
  font-size: 0.7rem;
  opacity: 0.8;
}

.large {
  font-size: 1rem;
  font-weight: 600;
}

footer {
  position: fixed;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 2rem;
  align-items: center;
  z-index: 10;
}

.bottom-nav {
  display: flex;
  gap: 0.5rem;
  background: #e75c8d;
  padding: 0.75rem;
  border-radius: 50px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  color: white;
  text-decoration: none;
  border-radius: 50px;
  transition: background 0.2s;
  font-weight: 500;
}

.nav-item.active,
.nav-item:hover {
  background: rgba(255, 255, 255, 0.2);
}

.support {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: rgba(0, 0, 0, 0.3);
  color: white;
  border: none;
  border-radius: 50px;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: all 0.2s;
}

.support:hover {
  background: rgba(0, 0, 0, 0.4);
  transform: translateY(-2px);
}

@media (max-width: 1200px) {
  main {
    grid-template-columns: 1fr;
    text-align: center;
    padding: 2rem;
  }

  .content-left,
  .content-right {
    padding: 0;
  }

  h1 {
    font-size: 4rem;
  }

  .sphere-container {
    margin: 3rem 0;
  }

  .tagline {
    font-size: 1.2rem;
  }

  header {
    padding: 1.5rem 2rem;
  }

  footer {
    bottom: 1rem;
    flex-direction: column;
  }
}"}]}
